/*
 * Shipped-core visibility contract (E11: SongCore ABI v1). Exactly the
 * SongCore public entry points are exported from libqianqian_songcore.so;
 * every FFmpeg / internal symbol is forced local. This mechanically proves
 * the AGENTS.md rule that no FFmpeg type or symbol leaks above SongCore.
 */
QIANQIAN_1.0 {
    global:
        songcore_abi_version;
        song_open;
        song_probe;
        song_audio_stream_count;
        song_audio_stream_info;
        song_select_stream;
        song_get_metadata;
        song_get_metadata_count;
        song_get_metadata_entry;
        song_get_artwork_count;
        song_get_artwork_item;
        song_read_pcm;
        song_seek;
        song_last_error;
        song_close;

    local:
        *;
};
